1	//! The `build` and `build-dev` subcommands: build the workspace's
2	//! release or its dev build, each by its configured command list. A
3	//! command per build, named with the `-dev` suffix as `run` and
4	//! `run-dev` are, so each names the build it makes and no dropped flag
5	//! makes the other. Neither touches the PATH: that is
6	//! `vc-x1 install`'s, which copies the release build there.
7	//!
8	//! - `vc-x1 build` runs `[build] release`, here
9	//!   `cargo build --release --locked`, and writes a stamp beside
10	//!   `[build] release-bin` naming the commit `@-` the build was made
11	//!   from and the state of the source. The lists leave the binaries in
12	//!   `target/`, off the PATH, so nothing there is replaced: the
13	//!   release build is run by `vc-x1 run` and copied by
14	//!   `vc-x1 install`, which runs this same build first, through
15	//!   [`build_params`] and [`build`], and reports what the stamp says.
16	//! - `vc-x1 build-dev` runs `[build] dev`, the dev build, and writes
17	//!   no stamp, since it is never installed.
18	//! - Where a build leaves its binary is the config's to say,
19	//!   `release-bin` and `dev-bin`: vc-x1 never works it out from cargo
20	//!   or the package's name.
21	//! - Both run their commands with the build's [`Provenance`] in the
22	//!   environment, `VC_X1_BUILD_COMMIT` and `VC_X1_BUILD_STATE`, as
23	//!   `validate` does, so every build of a run sees the same values
24	//!   and none recompiles for another. An artifact that compiles them
25	//!   in can say what it was built from wherever it is copied. vc-x1
26	//!   does, as semver build metadata in its banner,
27	//!   `0.85.7+d70cf9ecdfd9`, `.dirty` for a build with edits.
28	//! - Neither checks the repo's state: a release may be built from a
29	//!   cycle's bookmark, to try the release profile mid-cycle.
30	//! - The stamp is removed before the build and written after it
31	//!   passes, so a failed build never leaves a stamp describing the
32	//!   binary it failed to replace.
33	//! - The stamp also records the binary's size and modification time,
34	//!   its [`BinaryId`], so `install` can tell the binary `build` made
35	//!   from one rebuilt by hand or replaced since, for any artifact,
36	//!   whether or not it reports its commit.
37	//! - The lists are run by [`crate::command_list`], as `validate`'s
38	//!   are.
39	
40	use std::path::{Path, PathBuf};
41	
42	use clap::Args;
43	use log::{debug, info, warn};
44	
45	use crate::context::Context;
46	use crate::subcommand::SubcommandRunner;
47	use crate::version::SourceState;
48	
49	/// The stamp's suffix, appended to the release binary's path.
50	pub const STAMP_SUFFIX: &str = ".stamp";
51	
52	/// The variable carrying the build's commit to its commands.
53	pub const BUILD_COMMIT_VAR: &str = "VC_X1_BUILD_COMMIT";
54	
55	/// The variable carrying `state`, the state of the source code being
56	/// compiled, `clean` or `dirty`.
57	pub const BUILD_STATE_VAR: &str = "VC_X1_BUILD_STATE";
58	
59	/// Build the release.
60	#[derive(Args, Debug)]
61	pub struct BuildArgs {
62	    /// Workspace to build from [default: the workspace containing
63	    /// the current directory]
64	    #[arg(short = 'R', long, value_name = "DIR")]
65	    pub repo: Option<PathBuf>,
66	}
67	
68	/// Build the dev build.
69	#[derive(Args, Debug)]
70	pub struct BuildDevArgs {
71	    /// Workspace to build from [default: the workspace containing
72	    /// the current directory]
73	    #[arg(short = 'R', long, value_name = "DIR")]
74	    pub repo: Option<PathBuf>,
75	}
76	
77	/// What a build is made from: the work repo's `@-` and the state of
78	/// its source, read before the build runs.
79	#[derive(Debug, Clone, PartialEq, Eq)]
80	pub struct Provenance {
81	    /// The full commit id of the work repo's `@-`.
82	    pub commit: String,
83	    /// The state of the source code being compiled: clean when the
84	    /// work repo's `@` was empty, so the compiled code is exactly
85	    /// `commit`'s tree, else dirty. Never unknown, since it is read
86	    /// through jj.
87	    pub state: SourceState,
88	}
89	
90	impl Provenance {
91	    /// Read the provenance of the work repo at `root`, `label`
92	    /// prefixing an error.
93	    pub fn read(root: &Path, label: &str) -> Result<Self, String> {
94	        let commit = crate::jj::cid_of(root, "@-")
95	            .map_err(|e| format!("{label}: the commit `@-` in '{}': {e}", root.display()))?;
96	        let empty = crate::jj::is_empty(root, "@")
97	            .map_err(|e| format!("{label}: whether `@` is empty in '{}': {e}", root.display()))?;
98	        let state = if empty {
99	            SourceState::Clean
100	        } else {
101	            SourceState::Dirty
102	        };
103	        Ok(Provenance { commit, state })
104	    }
105	
106	    /// Read it, or warn and carry none, for a build that runs
107	    /// without it: the dev build and `validate`'s.
108	    pub fn read_or_warn(root: &Path, label: &str) -> Option<Self> {
109	        match Self::read(root, label) {
110	            Ok(p) => Some(p),
111	            Err(e) => {
112	                warn!("{e}, so the build carries no commit");
113	                None
114	            }
115	        }
116	    }
117	
118	    /// The two variables the build's commands get.
119	    pub fn env(&self) -> [(&'static str, &str); 2] {
120	        [
121	            (BUILD_COMMIT_VAR, self.commit.as_str()),
122	            (BUILD_STATE_VAR, self.state.as_str()),
123	        ]
124	    }
125	}
126	
127	/// The release binary's identity as the stamp records it: its size in
128	/// bytes and its modification time, nanoseconds since the Unix epoch.
129	/// A rebuild or a copy over it changes the time, and almost always
130	/// the size.
131	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
132	pub struct BinaryId {
133	    /// The file's length in bytes.
134	    pub size: u64,
135	    /// The file's modification time, nanoseconds since the epoch.
136	    pub mtime_ns: u128,
137	}
138	
139	impl BinaryId {
140	    /// Read the identity of the file at `bin`.
141	    pub fn of(bin: &Path) -> Result<Self, String> {
142	        let meta = std::fs::metadata(bin)
143	            .map_err(|e| format!("build: cannot read '{}': {e}", bin.display()))?;
144	        let mtime_ns = meta
145	            .modified()
146	            .map_err(|e| format!("build: no modification time for '{}': {e}", bin.display()))?
147	            .duration_since(std::time::UNIX_EPOCH)
148	            .map_err(|e| format!("build: '{}' is dated before 1970: {e}", bin.display()))?
149	            .as_nanos();
150	        Ok(BinaryId {
151	            size: meta.len(),
152	            mtime_ns,
153	        })
154	    }
155	}
156	
157	/// The variables for `provenance`, none when it is absent.
158	pub fn build_env(provenance: Option<&Provenance>) -> Vec<(&'static str, &str)> {
159	    // OK: no provenance is no variables, the build carrying no commit
160	    provenance.map(|p| p.env().to_vec()).unwrap_or_default()
161	}
162	
163	/// Where a release's stamp goes and the binary it describes.
164	#[derive(Debug, Clone, PartialEq, Eq)]
165	pub struct Stamp {
166	    /// The stamp file, `[build] release-bin` plus [`STAMP_SUFFIX`].
167	    pub path: PathBuf,
168	    /// The binary the stamp describes, `[build] release-bin`.
169	    pub bin: PathBuf,
170	}
171	
172	/// Per-invocation build inputs: the command's label, the list's key,
173	/// its commands, the directory to run them from, the build's
174	/// provenance, and the stamp a release writes.
175	#[derive(Debug)]
176	pub struct BuildParams {
177	    /// `build` or `build-dev`, prefixing the run's messages.
178	    pub label: &'static str,
179	    /// `build.release` or `build.dev`.
180	    pub key: &'static str,
181	    /// The commands, one element per invocation.
182	    pub commands: Vec<String>,
183	    /// The work repo root the commands run from.
184	    pub root: PathBuf,
185	    /// The build's provenance, required for a release, best effort
186	    /// for the dev build.
187	    pub provenance: Option<Provenance>,
188	    /// The release's stamp, `None` for the dev build.
189	    pub stamp: Option<Stamp>,
190	}
191	
192	impl TryFrom<&BuildArgs> for BuildParams {
193	    type Error = String;
194	
195	    /// The release: see [`build_params`].
196	    fn try_from(a: &BuildArgs) -> Result<Self, String> {
197	        build_params(false, a.repo.as_deref())
198	    }
199	}
200	
201	impl TryFrom<&BuildDevArgs> for BuildParams {
202	    type Error = String;
203	
204	    /// The dev build: see [`build_params`].
205	    fn try_from(a: &BuildDevArgs) -> Result<Self, String> {
206	        build_params(true, a.repo.as_deref())
207	    }
208	}
209	
210	/// Resolve the workspace root (from `-R` or the cwd), take the chosen
211	/// list, read the provenance, and for a release resolve `release-bin`.
212	/// A release's every miss is an error here, before anything runs, and
213	/// the dev build's provenance is best effort.
214	pub fn build_params(dev: bool, repo: Option<&Path>) -> Result<BuildParams, String> {
215	    let (label, key) = if dev {
216	        ("build-dev", "build.dev")
217	    } else {
218	        ("build", "build.release")
219	    };
220	    let root = match repo {
221	        Some(p) => crate::common::find_workspace_root_from(p)
222	            .ok_or_else(|| format!("{label}: '{}' is not in a vc-x1 workspace", p.display()))?,
223	        None => crate::common::find_workspace_root()
224	            .ok_or_else(|| format!("{label}: not in a vc-x1 workspace (no config found)"))?,
225	    };
226	    let commands = crate::command_list::load(&root, key, label)?;
227	    let (provenance, stamp) = if dev {
228	        (Provenance::read_or_warn(&root, label), None)
229	    } else {
230	        let bin = release_bin(&root)?;
231	        let provenance = Provenance::read(&root, label)?;
232	        let stamp = Stamp {
233	            path: stamp_path(&bin),
234	            bin,
235	        };
236	        (Some(provenance), Some(stamp))
237	    };
238	    Ok(BuildParams {
239	        label,
240	        key,
241	        commands,
242	        root,
243	        provenance,
244	        stamp,
245	    })
246	}
