290	impl SubcommandRunner for BuildArgs {
291	    type Params = BuildParams;
292	
293	    /// Delegate to the `TryFrom<&BuildArgs>` impl above.
294	    fn to_params(&self) -> Result<Self::Params, String> {
295	        BuildParams::try_from(self)
296	    }
297	
298	    /// Run the `build` op (`ctx` unused: the op is fully
299	    /// parameterized by `Params`).
300	    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
301	        build(params)
302	    }
303	}
304	
305	impl SubcommandRunner for BuildDevArgs {
306	    type Params = BuildParams;
307	
308	    /// Delegate to the `TryFrom<&BuildDevArgs>` impl above.
309	    fn to_params(&self) -> Result<Self::Params, String> {
310	        BuildParams::try_from(self)
311	    }
312	
313	    /// Run the same op as `build`, its params naming the dev build.
314	    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
315	        build(params)
316	    }
317	}
318	
319	/// What a release build did to its binary, from its identity before
320	/// and after the list ran: `up to date` when the list left it as it
321	/// was, as cargo does when nothing changed, `built` otherwise.
322	pub fn outcome(before: Option<BinaryId>, after: BinaryId) -> &'static str {
323	    if before == Some(after) {
324	        "up to date"
325	    } else {
326	        "built"
327	    }
328	}
329	
330	/// Run the list from the root with the provenance in its
331	/// environment, and for a release remove the old stamp first and
332	/// write the new one once the list passes, saying whether the binary
333	/// was built or already up to date.
334	pub fn build(params: &BuildParams) -> Result<(), Box<dyn std::error::Error>> {
335	    debug!("{}: entry params={params:?}", params.label);
336	    let before = params
337	        .stamp
338	        .as_ref()
339	        .and_then(|stamp| BinaryId::of(&stamp.bin).ok());
340	    if let Some(stamp) = &params.stamp {
341	        match std::fs::remove_file(&stamp.path) {
342	            Ok(()) => debug!("build: removed the old stamp {}", stamp.path.display()),
343	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
344	            Err(e) => {
345	                return Err(format!(
346	                    "build: cannot remove the old stamp '{}': {e}",
347	                    stamp.path.display()
348	                )
349	                .into());
350	            }
351	        }
352	    }
353	    let env = build_env(params.provenance.as_ref());
354	    crate::command_list::run(
355	        &params.root,
356	        params.key,
357	        &params.commands,
358	        &env,
359	        params.label,
360	    )?;
361	    let (Some(stamp), Some(provenance)) = (&params.stamp, &params.provenance) else {
362	        return Ok(());
363	    };
364	    if !stamp.bin.is_file() {
365	        return Err(format!(
366	            "build: `{}` passed but left no binary at '{}', so no stamp is written: \
367	             check `build.release-bin`",
368	            params.key,
369	            stamp.bin.display()
370	        )
371	        .into());
372	    }
373	    let id = BinaryId::of(&stamp.bin)?;
374	    std::fs::write(&stamp.path, render_stamp(provenance, id)).map_err(|e| {
375	        format!(
376	            "build: cannot write the stamp '{}': {e}",
377	            stamp.path.display()
378	        )
379	    })?;
380	    let short = &provenance.commit[..provenance.commit.len().min(12)];
381	    let state = match provenance.state {
382	        SourceState::Clean => "state clean, `@` empty",
383	        _ => "state dirty, `@` held edits, so the build is not exactly that commit",
384	    };
385	    info!(
386	        "build: {} {}, from {short}, {state}",
387	        stamp.bin.display(),
388	        outcome(before, id)
389	    );
390	    Ok(())
391	}
