1	//! The `install` subcommand: build the release when it is out of
2	//! date, then copy it into the install directory, the one command that
3	//! touches the PATH, after reporting what it is copying.
4	//!
5	//! - It runs `[build] release` first, exactly as `vc-x1 build` does,
6	//!   the stamp included. Cargo rebuilds only what changed, so with
7	//!   nothing changed the binary already tested is the one copied, and
8	//!   a missing or stale one is built rather than refused.
9	//! - The binary is `[build] release-bin`, with its stamp beside it.
10	//!   The destination is the one directory `[install] dir` names, `~`
11	//!   expanded, so the committed value fits every machine, and the
12	//!   binary keeps its file name there. `$PATH` is not searched.
13	//! - The report says what is being copied: the version and commit the
14	//!   binary's `-V` shows, whether that commit is `main` and
15	//!   `main@origin`, its state, a suffixed version, and whether the
16	//!   stamp still matches the binary. It refuses nothing: which builds
17	//!   may be installed is the release process's call, a cycle's Land
18	//!   here, and a project releasing from a branch or a tag makes it
19	//!   differently.
20	//! - It refuses only when the copy itself would be wrong, every reason
21	//!   listed: no binary at `release-bin` after the build, a binary whose
22	//!   `-V` will not run, or a missing install directory.
23	//! - The copy is a temporary file beside the destination renamed into
24	//!   place, so the binary installed is the one tested, a running copy
25	//!   of the old one is undisturbed, and a failed copy leaves the old
26	//!   one.
27	//! - `--dry-run` builds and reports, and copies nothing.
28	//! - A workspace with no `[install] dir` has nothing to install, and
29	//!   install says so before building anything.
30	
31	use std::path::{Path, PathBuf};
32	
33	use clap::Args;
34	use log::{debug, info};
35	
36	use crate::build_cmd::{BinaryId, BuildParams, build_params, release_bin, stamp_path};
37	use crate::context::Context;
38	use crate::options_flags::dry_run::DryRunFlag;
39	use crate::subcommand::SubcommandRunner;
40	use crate::version::SourceState;
41	
42	/// The trunk the report compares the binary's commit with.
43	const TRUNK: &str = "main";
44	
45	/// Copy the release build into the install directory.
46	#[derive(Args, Debug)]
47	pub struct InstallArgs {
48	    #[command(flatten)]
49	    pub dry_run: DryRunFlag,
50	
51	    /// Workspace to install from [default: the workspace containing
52	    /// the current directory]
53	    #[arg(short = 'R', long, value_name = "DIR")]
54	    pub repo: Option<PathBuf>,
55	}
56	
57	/// What the stamp beside the release binary records, as read back.
58	#[derive(Debug, Clone, PartialEq, Eq)]
59	pub struct StampRecord {
60	    /// The commit the release was built from.
61	    pub commit: String,
62	    /// The state of the source code that was compiled.
63	    pub state: Option<SourceState>,
64	    /// The binary's identity when it was stamped.
65	    pub id: Option<BinaryId>,
66	}
67	
68	/// What the release binary's `-V` says: its version and, from the
69	/// build metadata after `+`, its commit and the state after it.
70	#[derive(Debug, Clone, PartialEq, Eq)]
71	pub struct Reported {
72	    /// The version before any `+`.
73	    pub version: String,
74	    /// The commit prefix after `+`, when the build reports one.
75	    pub commit: Option<String>,
76	    /// The state after the commit, `dirty` or `unknown`, when not clean.
77	    pub state: Option<String>,
78	}
79	
80	/// Everything the report and the refusals judge, gathered before
81	/// either is made.
82	#[derive(Debug, Clone, PartialEq, Eq)]
83	pub struct Facts {
84	    /// The local trunk's commit, `None` when there is no such bookmark.
85	    pub trunk: Option<String>,
86	    /// The remote trunk's commit, `None` when it is not known.
87	    pub trunk_origin: Option<String>,
88	    /// The manifest's version.
89	    pub version: String,
90	    /// The stamp, `None` when there is none.
91	    pub stamp: Option<StampRecord>,
92	    /// The release binary's identity, `None` when it is missing.
93	    pub bin_id: Option<BinaryId>,
94	    /// What the release binary's `-V` said, `None` when it could not be
95	    /// run or read.
96	    pub reported: Option<Reported>,
97	    /// True when the destination directory exists.
98	    pub dest_dir_exists: bool,
99	}
100	
101	/// Per-invocation install inputs: the release build to run first,
102	/// where its binary is and where it goes, and whether to copy.
103	#[derive(Debug)]
104	pub struct InstallParams {
105	    /// The work repo root.
106	    pub root: PathBuf,
107	    /// The release build, `vc-x1 build`'s, run before anything else.
108	    pub release: BuildParams,
109	    /// The release binary, `[build] release-bin`.
110	    pub bin: PathBuf,
111	    /// The destination, `[install] dir` joined with the binary's name.
112	    pub dest: PathBuf,
113	    /// Build and report, and copy nothing.
114	    pub dry_run: bool,
115	}
116	
117	impl TryFrom<&InstallArgs> for InstallParams {
118	    type Error = String;
119	
120	    /// Resolve the workspace, the install directory, and the release
121	    /// build. A missing config key is an error here, before the build
122	    /// runs, and every fact about the binary is gathered after it.
123	    fn try_from(a: &InstallArgs) -> Result<Self, String> {
124	        let root = match &a.repo {
125	            Some(p) => crate::common::find_workspace_root_from(p)
126	                .ok_or_else(|| format!("install: '{}' is not in a vc-x1 workspace", p.display()))?,
127	            None => crate::common::find_workspace_root()
128	                .ok_or_else(|| "install: not in a vc-x1 workspace (no config found)".to_string())?,
129	        };
130	        let dest_dir = install_dir(&root)?;
131	        let release = build_params(false, Some(&root))?;
132	        let bin = release_bin(&root)?;
133	        let name = bin
134	            .file_name()
135	            .ok_or_else(|| format!("install: '{}' names no file", bin.display()))?;
136	        let dest = dest_dir.join(name);
137	        Ok(InstallParams {
138	            root,
139	            release,
140	            bin,
141	            dest,
142	            dry_run: a.dry_run.value,
143	        })
144	    }
145	}
