241	/// Parse `-V`'s output: the first line `<name> <version>[+<commit>[.<state>]] ...`
242	/// whose second word starts with a digit, so a line printed before the
243	/// version is passed over. `None` when no line has a version, which
244	/// install refuses as unreadable.
245	pub fn parse_reported(output: &str) -> Option<Reported> {
246	    let word = output.lines().find_map(|line| {
247	        line.split_whitespace()
248	            .nth(1)
249	            .filter(|w| w.starts_with(|c: char| c.is_ascii_digit()))
250	    })?;
251	    let (version, meta) = match word.split_once('+') {
252	        Some((v, m)) => (v, Some(m)),
253	        None => (word, None),
254	    };
255	    let (commit, state) = match meta {
256	        None => (None, None),
257	        Some(m) => match m.split_once('.') {
258	            Some((c, s)) => (Some(c.to_string()), Some(s.to_string())),
259	            None => (Some(m.to_string()), None),
260	        },
261	    };
262	    Some(Reported {
263	        version: version.to_string(),
264	        commit,
265	        state,
266	    })
267	}
