269	/// The 12-character form of a commit id, for messages.
270	fn short(id: &str) -> &str {
271	    &id[..id.len().min(12)]
272	}
273	
274	/// True when the commit prefix `c` names the commit id `id`.
275	fn names(c: &str, id: Option<&String>) -> bool {
276	    id.is_some_and(|id| id.starts_with(c))
277	}
