279	/// The report: what is being copied, one fact per line, for the user
280	/// to judge. Nothing in it refuses.
281	pub fn report(f: &Facts) -> Vec<String> {
282	    let mut out = Vec::new();
283	    let Some(r) = &f.reported else {
284	        return out;
285	    };
286	    let mut version = format!("version {}", r.version);
287	    if r.version.contains('-') {
288	        version.push_str(", a suffixed (pre-release) version");
289	    }
290	    if r.version != f.version {
291	        version.push_str(&format!(", the manifest's is {}", f.version));
292	    }
293	    out.push(version);
294	    // The stamp speaks for the binary only while it still matches it.
295	    let stamp = f
296	        .stamp
297	        .as_ref()
298	        .filter(|st| st.id.is_some() && st.id == f.bin_id);
299	    // The binary's own word first, the stamp's when it reports none.
300	    let commit = r
301	        .commit
302	        .clone()
303	        .or_else(|| stamp.map(|st| short(&st.commit).to_string()));
304	    match &commit {
305	        None => out.push("commit unknown: the binary reports none and no stamp matches it".into()),
306	        Some(c) => {
307	            let on_trunk = names(c, f.trunk.as_ref());
308	            let on_origin = names(c, f.trunk_origin.as_ref());
309	            let where_ = match (on_trunk, on_origin) {
310	                (true, true) => format!("`{TRUNK}` and `{TRUNK}@origin`"),
311	                (true, false) => format!("`{TRUNK}`, not yet `{TRUNK}@origin`"),
312	                (false, true) => format!("`{TRUNK}@origin`, not the local `{TRUNK}`"),
313	                (false, false) => format!("not `{TRUNK}`"),
314	            };
315	            out.push(format!("commit {c}, {where_}"));
316	        }
317	    }
318	    let state = match (&r.commit, &r.state, stamp) {
319	        (Some(_), Some(s), _) => s.clone(),
320	        (Some(_), None, _) => "clean".to_string(),
321	        // OK: a stamp with no readable state reports as unknown
322	        (None, _, Some(st)) => st
323	            .state
324	            .map(SourceState::as_str)
325	            .unwrap_or("unknown")
326	            .into(),
327	        (None, _, None) => "unknown".to_string(),
328	    };
329	    out.push(format!("state {state}"));
330	    match (&f.stamp, stamp) {
331	        (None, _) => out.push("no stamp: `vc-x1 build` did not make this binary".to_string()),
332	        (Some(_), None) => out.push(
333	            "the stamp does not match the binary: it was rebuilt by hand or replaced after \
334	             `vc-x1 build`"
335	                .to_string(),
336	        ),
337	        (Some(_), Some(st)) => {
338	            if let Some(c) = &r.commit
339	                && !st.commit.starts_with(c.as_str())
340	            {
341	                out.push(format!(
342	                    "the stamp names commit {}, the binary reports {c}",
343	                    short(&st.commit)
344	                ));
345	            } else {
346	                out.push("the stamp matches the binary".to_string());
347	            }
348	        }
349	    }
350	    out
351	}
