353	/// Every reason the copy itself would be wrong, empty when it may go.
354	pub fn refusals(f: &Facts, bin: &Path, dest: &Path) -> Vec<String> {
355	    let mut out = Vec::new();
356	    if f.bin_id.is_none() {
357	        out.push(format!(
358	            "no binary at '{}': build it with `vc-x1 build`",
359	            bin.display()
360	        ));
361	    } else if f.reported.is_none() {
362	        out.push(format!("'{}' -V could not be run or read", bin.display()));
363	    }
364	    if !f.dest_dir_exists {
365	        // OK: dest is a directory joined with a file name, so it has a parent
366	        let dir = dest.parent().unwrap_or(dest);
367	        out.push(format!(
368	            "the `install.dir` directory '{}' does not exist",
369	            dir.display()
370	        ));
371	    }
372	    out
373	}
