375	/// Copy `bin` to `dest` as a temporary file beside it renamed into
376	/// place, so `dest` is never half written and a running copy of the
377	/// old binary is undisturbed. The temporary file is removed on failure.
378	pub fn deploy(bin: &Path, dest: &Path) -> Result<(), String> {
379	    // OK: dest is a directory joined with a file name, so both exist
380	    let dir = dest.parent().unwrap_or(Path::new("."));
381	    // OK: dest is joined with the release binary's file name, so it has one
382	    let name = dest
383	        .file_name()
384	        .map(|n| n.to_string_lossy().into_owned())
385	        .unwrap_or_default();
386	    let tmp = dir.join(format!(".{name}.vc-x1-install"));
387	    let result = std::fs::copy(bin, &tmp)
388	        .map_err(|e| format!("install: cannot copy to '{}': {e}", tmp.display()))
389	        .and_then(|_| {
390	            std::fs::rename(&tmp, dest).map_err(|e| {
391	                format!(
392	                    "install: cannot move '{}' into '{}': {e}",
393	                    tmp.display(),
394	                    dest.display()
395	                )
396	            })
397	        });
398	    if result.is_err() {
399	        std::fs::remove_file(&tmp).ok();
400	    }
401	    result
402	}
