686	        assert_eq!(
687	            parse_reported("wink: hi\n"),
688	            None,
689	            "no version is unreadable"
690	        );
691	        assert_eq!(parse_reported(""), None);
692	    }
693	
694	    #[test]
695	    fn expand_dir_forms() {
696	        let cfg = Path::new("/w");
697	        let home = Path::new("/home/u");
698	        assert_eq!(
699	            expand_dir(cfg, "~/.cargo/bin", Some(home)).unwrap(),
700	            PathBuf::from("/home/u/.cargo/bin")
701	        );
702	        assert_eq!(
703	            expand_dir(cfg, "~", Some(home)).unwrap(),
704	            PathBuf::from("/home/u")
705	        );
706	        assert_eq!(
707	            expand_dir(cfg, "/opt/bin", Some(home)).unwrap(),
708	            PathBuf::from("/opt/bin")
709	        );
710	        assert_eq!(
711	            expand_dir(cfg, "out/bin", Some(home)).unwrap(),
712	            PathBuf::from("/w/out/bin")
713	        );
714	        assert!(expand_dir(cfg, "~/x", None).unwrap_err().contains("HOME"));
715	        assert_eq!(
716	            expand_dir(cfg, "~user/x", Some(home)).unwrap(),
717	            PathBuf::from("/w/~user/x"),
718	            "only `~` and `~/` expand"
719	        );
720	    }
721	
722	    /// A stamp written by build reads back whole, and a file with no
723	    /// commit is no stamp.
724	    #[test]
725	    fn read_stamp_reads_builds_stamp() {
726	        let dir = tempdir("stamp");
727	        let path = dir.join("app.stamp");
728	        let prov = crate::build_cmd::Provenance {
729	            commit: C.to_string(),
730	            state: SourceState::Clean,
731	        };
732	        std::fs::write(&path, crate::build_cmd::render_stamp(&prov, ID)).unwrap();
733	        assert_eq!(
734	            read_stamp(&path),
735	            Some(StampRecord {
736	                commit: C.to_string(),
737	                state: Some(SourceState::Clean),
738	                id: Some(ID),
739	            })
740	        );
741	        std::fs::write(&path, "state = \"clean\"\n").unwrap();
742	        assert_eq!(read_stamp(&path), None);
743	        assert_eq!(read_stamp(&dir.join("absent")), None);
744	        std::fs::remove_dir_all(&dir).ok();
745	    }
746	
747	    /// The deploy replaces the destination whole and leaves no
748	    /// temporary file, keeping the binary's permissions.
749	    #[test]
750	    fn deploy_replaces_the_destination() {
751	        use std::os::unix::fs::PermissionsExt;
752	        let dir = tempdir("deploy");
753	        let bin = dir.join("release");
754	        std::fs::write(&bin, "the new release").unwrap();
755	        std::fs::set_permissions(&bin, std::fs::Permissions::from_mode(0o755)).unwrap();
756	        let dest_dir = dir.join("bin");
757	        std::fs::create_dir_all(&dest_dir).unwrap();
758	        let dest = dest_dir.join("app");
759	        std::fs::write(&dest, "the old release").unwrap();
760	        deploy(&bin, &dest).unwrap();
761	        assert_eq!(std::fs::read_to_string(&dest).unwrap(), "the new release");
762	        let mode = std::fs::metadata(&dest).unwrap().permissions().mode() & 0o777;
763	        assert_eq!(mode, 0o755);
764	        let left: Vec<_> = std::fs::read_dir(&dest_dir).unwrap().collect();
765	        assert_eq!(left.len(), 1, "no temporary file left");
766	        std::fs::remove_dir_all(&dir).ok();
767	    }
768	
769	    /// The copy goes when it is not refused, whatever the report says,
770	    /// a dry run copies nothing, and a refusal lists every reason and
771	    /// copies nothing.
772	    #[test]
773	    fn copy_reported_copies_unless_refused() {
774	        let dir = tempdir("install");
775	        let bin = dir.join("release");
776	        std::fs::write(&bin, "the release").unwrap();
777	        std::fs::create_dir_all(dir.join("bin")).unwrap();
778	        let dest = dir.join("bin/app");
779	        let mut facts = good();
780	        facts.version = "0.85.7-3".to_string();
781	        facts.stamp = None;
782	        copy_reported(&bin, &dest, &facts, true).unwrap();
783	        assert!(!dest.exists(), "a dry run copied");
784	        copy_reported(&bin, &dest, &facts, false).unwrap();
785	        assert_eq!(std::fs::read_to_string(&dest).unwrap(), "the release");
786	        std::fs::remove_file(&dest).unwrap();
787	        facts.reported = None;
788	        facts.dest_dir_exists = false;
789	        let e = copy_reported(&bin, &dest, &facts, false)
790	            .unwrap_err()
791	            .to_string();
792	        assert!(e.contains("refused, nothing copied"), "{e}");
793	        assert!(
794	            e.contains("could not be run") && e.contains("does not exist"),
795	            "every reason: {e}"
796	        );
797	        assert!(!dest.exists());
798	        std::fs::remove_dir_all(&dir).ok();
799	    }
800	
801	    /// The install directory is checked before the release build is
802	    /// resolved, so a workspace with nothing to install builds nothing.
803	    #[test]
804	    fn no_install_dir_is_an_error_before_the_build() {
805	        let dir = tempdir("nodir");
806	        std::fs::write(
807	            dir.join(".vc-config.md"),
808	            "```toml\n[repos]\nwork = \".\"\n[build]\nrelease = [\"true\"]\n\
809	             release-bin = \"app\"\n```\n",
810	        )
811	        .unwrap();
812	        let args = InstallArgs {
813	            dry_run: DryRunFlag { value: true },
814	            repo: Some(dir.clone()),
815	        };
816	        let e = InstallParams::try_from(&args).unwrap_err();
817	        assert!(e.contains("nothing to install"), "{e}");
818	        std::fs::remove_dir_all(&dir).ok();
819	    }
820	
821	    /// A failed copy leaves the destination as it was and no temporary
822	    /// file.
823	    #[test]
824	    fn a_failed_deploy_leaves_the_old_binary() {
825	        let dir = tempdir("deployfail");
826	        let dest = dir.join("app");
827	        std::fs::write(&dest, "the old release").unwrap();
828	        let e = deploy(&dir.join("absent"), &dest).unwrap_err();
829	        assert!(e.contains("cannot copy"), "{e}");
830	        assert_eq!(std::fs::read_to_string(&dest).unwrap(), "the old release");
831	        assert_eq!(std::fs::read_dir(&dir).unwrap().count(), 1);
832	        std::fs::remove_dir_all(&dir).ok();
833	    }
