248	/// `[build] release-bin` at `root`, resolved against the config
249	/// file's directory, or as is when absolute. Required for a release,
250	/// since the stamp sits beside it.
251	pub fn release_bin(root: &Path) -> Result<PathBuf, String> {
252	    let cfg = crate::config_md::load(root)
253	        .map_err(|e| format!("build: {e}"))?
254	        .ok_or_else(|| format!("build: no config in '{}'", root.display()))?;
255	    let value = crate::toml_simple::toml_get(&cfg.map, "build.release-bin").ok_or_else(|| {
256	        format!(
257	            "build: {}: no `build.release-bin`, the binary `build.release` leaves, \
258	             which the stamp is written beside (see `vc-x1 config work`)",
259	            cfg.path.display()
260	        )
261	    })?;
262	    // OK: a loaded config's path is a file, so it has a parent
263	    let cfg_dir = cfg.path.parent().unwrap_or(root);
264	    Ok(crate::common::resolve_repo_path(cfg_dir, value))
265	}
