267	/// The stamp file for the binary at `bin`.
268	pub fn stamp_path(bin: &Path) -> PathBuf {
269	    let mut s = bin.as_os_str().to_os_string();
270	    s.push(STAMP_SUFFIX);
271	    PathBuf::from(s)
272	}
