274	/// The stamp's text: a comment saying what it is, then `commit`,
275	/// `state`, `size`, and `mtime-ns`, keys `toml_simple` reads back.
276	pub fn render_stamp(provenance: &Provenance, id: BinaryId) -> String {
277	    format!(
278	        "# vc-x1 build stamp: the commit the binary beside it was built from\n\
279	         commit = \"{}\"\n\
280	         state = \"{}\"\n\
281	         size = {}\n\
282	         mtime-ns = {}\n",
283	        provenance.commit,
284	        provenance.state.as_str(),
285	        id.size,
286	        id.mtime_ns
287	    )
288	}
