1	//! The `install` subcommand: build the release when it is out of
2	//! date, then copy it into the install directory, the one command that
3	//! touches the PATH, after reporting what it is copying.
4	//!
5	//! - It runs `[build] release` first, exactly as `vc-x1 build` does,
6	//!   the stamp included. Cargo rebuilds only what changed, so with
7	//!   nothing changed the binary already tested is the one copied, and
8	//!   a missing or stale one is built rather than refused.
9	//! - The binary is `[build] release-bin`, with its stamp beside it.
10	//!   The destination is the one directory `[install] dir` names, `~`
11	//!   expanded, so the committed value fits every machine, and the
12	//!   binary keeps its file name there. `$PATH` is not searched.
13	//! - The report says what is being copied: the version and commit the
14	//!   binary's `-V` shows, whether that commit is `main` and
15	//!   `main@origin`, its state, a suffixed version, and whether the
16	//!   stamp still matches the binary. It refuses nothing: which builds
17	//!   may be installed is the release process's call, a cycle's Land
18	//!   here, and a project releasing from a branch or a tag makes it
19	//!   differently.
20	//! - It refuses only when the copy itself would be wrong, every reason
21	//!   listed: no binary at `release-bin` after the build, a binary whose
22	//!   `-V` will not run, or a missing install directory.
23	//! - The copy is a temporary file beside the destination renamed into
24	//!   place, so the binary installed is the one tested, a running copy
25	//!   of the old one is undisturbed, and a failed copy leaves the old
26	//!   one.
27	//! - `--dry-run` builds and reports, and copies nothing.
28	//! - A workspace with no `[install] dir` has nothing to install, and
29	//!   install says so before building anything.
30	
31	use std::path::{Path, PathBuf};
32	
33	use clap::Args;
34	use log::{debug, info};
35	
36	use crate::build_cmd::{BinaryId, BuildParams, build_params, release_bin, stamp_path};
37	use crate::context::Context;
38	use crate::options_flags::dry_run::DryRunFlag;
39	use crate::subcommand::SubcommandRunner;
40	use crate::version::SourceState;
41	
42	/// The trunk the report compares the binary's commit with.
43	const TRUNK: &str = "main";
44	
45	/// Copy the release build into the install directory.
46	#[derive(Args, Debug)]
47	pub struct InstallArgs {
48	    #[command(flatten)]
49	    pub dry_run: DryRunFlag,
50	
51	    /// Workspace to install from [default: the workspace containing
52	    /// the current directory]
53	    #[arg(short = 'R', long, value_name = "DIR")]
54	    pub repo: Option<PathBuf>,
55	}
56	
57	/// What the stamp beside the release binary records, as read back.
58	#[derive(Debug, Clone, PartialEq, Eq)]
59	pub struct StampRecord {
60	    /// The commit the release was built from.
61	    pub commit: String,
62	    /// The state of the source code that was compiled.
63	    pub state: Option<SourceState>,
64	    /// The binary's identity when it was stamped.
65	    pub id: Option<BinaryId>,
66	}
