404	impl SubcommandRunner for InstallArgs {
405	    type Params = InstallParams;
406	
407	    /// Delegate to the `TryFrom<&InstallArgs>` impl above.
408	    fn to_params(&self) -> Result<Self::Params, String> {
409	        InstallParams::try_from(self)
410	    }
411	
412	    /// Run the `install` op (`ctx` unused: the op is fully
413	    /// parameterized by `Params`).
414	    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
415	        install(params)
416	    }
417	}
