1	//! The `install` subcommand: build the release when it is out of
2	//! date, then copy it into the install directory, the one command that
3	//! touches the PATH, after reporting what it is copying.
4	//!
5	//! - It runs `[build] release` first, exactly as `vc-x1 build` does.
6	//!   Cargo rebuilds only what changed, so with
7	//!   nothing changed the binary already tested is the one copied, and
8	//!   a missing or stale one is built rather than refused.
9	//! - The binary is `[build] release-bin`. The destination is the one directory `[install] dir` names, `~`
10	//!   expanded, so the committed value fits every machine, and the
11	//!   binary keeps its file name there. `$PATH` is not searched.
12	//! - The report says what is being copied: the version and commit the
13	//!   binary's `-V` shows, whether that commit is `main` and
14	//!   `main@origin`, its state, and a suffixed version. A binary whose
15	//!   `-V` carries no commit is reported as unknown. It refuses
16	//!   nothing: which builds
17	//!   may be installed is the release process's call, a cycle's Land
18	//!   here, and a project releasing from a branch or a tag makes it
19	//!   differently.
20	//! - It refuses only when the copy itself would be wrong, every reason
21	//!   listed: no binary at `release-bin` after the build, a binary whose
22	//!   `-V` will not run, or a missing install directory.
23	//! - The copy is a temporary file beside the destination renamed into
24	//!   place, so the binary installed is the one tested, a running copy
25	//!   of the old one is undisturbed, and a failed copy leaves the old
26	//!   one.
27	//! - `--dry-run` builds and reports, and copies nothing.
28	//! - A workspace with no `[install] dir` has nothing to install, and
29	//!   install says so before building anything.
30	
31	use std::path::{Path, PathBuf};
32	
33	use clap::Args;
34	use log::{debug, info};
35	
36	use crate::build_cmd::{BuildParams, build_params, release_bin};
37	use crate::context::Context;
38	use crate::options_flags::dry_run::DryRunFlag;
39	use crate::subcommand::SubcommandRunner;
40	
41	/// The trunk the report compares the binary's commit with.
42	const TRUNK: &str = "main";
43	
44	/// Copy the release build into the install directory.
45	#[derive(Args, Debug)]
46	pub struct InstallArgs {
47	    #[command(flatten)]
48	    pub dry_run: DryRunFlag,
49	
50	    /// Workspace to install from [default: the workspace containing
51	    /// the current directory]
52	    #[arg(short = 'R', long, value_name = "DIR")]
53	    pub repo: Option<PathBuf>,
54	}
55	
56	/// What the release binary's `-V` says: its version and, from the
57	/// build metadata after `+`, its commit and the state after it.
58	#[derive(Debug, Clone, PartialEq, Eq)]
59	pub struct Reported {
60	    /// The version before any `+`.
61	    pub version: String,
62	    /// The commit prefix after `+`, when the build reports one.
63	    pub commit: Option<String>,
64	    /// The state after the commit, `dirty` or `unknown`, when not clean.
65	    pub state: Option<String>,
66	}
67	
68	/// Everything the report and the refusals judge, gathered before
69	/// either is made.
70	#[derive(Debug, Clone, PartialEq, Eq)]
71	pub struct Facts {
72	    /// The local trunk's commit, `None` when there is no such bookmark.
73	    pub trunk: Option<String>,
74	    /// The remote trunk's commit, `None` when it is not known.
75	    pub trunk_origin: Option<String>,
76	    /// The manifest's version.
77	    pub version: String,
78	    /// True when the release binary is there.
79	    pub bin_exists: bool,
80	    /// What the release binary's `-V` said, `None` when it could not be
81	    /// run or read.
82	    pub reported: Option<Reported>,
83	    /// True when the destination directory exists.
84	    pub dest_dir_exists: bool,
85	}
86	
87	/// Per-invocation install inputs: the release build to run first,
88	/// where its binary is and where it goes, and whether to copy.
89	#[derive(Debug)]
90	pub struct InstallParams {
91	    /// The work repo root.
92	    pub root: PathBuf,
93	    /// The release build, `vc-x1 build`'s, run before anything else.
94	    pub release: BuildParams,
95	    /// The release binary, `[build] release-bin`.
96	    pub bin: PathBuf,
97	    /// The destination, `[install] dir` joined with the binary's name.
98	    pub dest: PathBuf,
99	    /// Build and report, and copy nothing.
100	    pub dry_run: bool,
101	}
102	
103	impl TryFrom<&InstallArgs> for InstallParams {
104	    type Error = String;
105	
106	    /// Resolve the workspace, the install directory, and the release
107	    /// build. A missing config key is an error here, before the build
108	    /// runs, and every fact about the binary is gathered after it.
109	    fn try_from(a: &InstallArgs) -> Result<Self, String> {
110	        let root = match &a.repo {
111	            Some(p) => crate::common::find_workspace_root_from(p)
112	                .ok_or_else(|| format!("install: '{}' is not in a vc-x1 workspace", p.display()))?,
113	            None => crate::common::find_workspace_root()
114	                .ok_or_else(|| "install: not in a vc-x1 workspace (no config found)".to_string())?,
115	        };
116	        let dest_dir = install_dir(&root)?;
117	        let release = build_params(false, Some(&root))?;
118	        let bin = release_bin(&root)?;
119	        let name = bin
120	            .file_name()
121	            .ok_or_else(|| format!("install: '{}' names no file", bin.display()))?;
122	        let dest = dest_dir.join(name);
123	        Ok(InstallParams {
124	            root,
125	            release,
126	            bin,
127	            dest,
128	            dry_run: a.dry_run.value,
129	        })
130	    }
131	}
132	
133	/// Gather the facts about the binary at `bin`, after the build, and
134	/// about the trunk of the work repo at `root`.
135	pub fn gather(root: &Path, bin: &Path, dest: &Path) -> Result<Facts, String> {
136	    Ok(Facts {
137	        trunk: crate::jj::cid_of(root, TRUNK).ok(),
138	        trunk_origin: crate::jj::cid_of(root, &format!("{TRUNK}@origin")).ok(),
139	        version: manifest_version(root)?,
140	        bin_exists: bin.is_file(),
141	        reported: run_version(bin).as_deref().and_then(parse_reported),
142	        dest_dir_exists: dest.parent().is_some_and(Path::is_dir),
143	    })
144	}
145	
146	/// `[install] dir` at `root`: `~` and `~/...` against the home
147	/// directory, any other relative value against the config file's
148	/// directory, an absolute one as is. Its absence is the workspace
149	/// having nothing to install.
150	pub fn install_dir(root: &Path) -> Result<PathBuf, String> {
151	    let cfg = crate::config_md::load(root)
152	        .map_err(|e| format!("install: {e}"))?
153	        .ok_or_else(|| format!("install: no config in '{}'", root.display()))?;
154	    let value = crate::toml_simple::toml_get(&cfg.map, "install.dir").ok_or_else(|| {
155	        format!(
156	            "install: {}: no `install.dir`, so this workspace has nothing to install. Name the \
157	             directory the release build is copied into, such as `~/.cargo/bin` (see `vc-x1 \
158	             config work`)",
159	            cfg.path.display()
160	        )
161	    })?;
162	    // OK: a loaded config's path is a file, so it has a parent
163	    let cfg_dir = cfg.path.parent().unwrap_or(root);
164	    expand_dir(cfg_dir, value, crate::jj::session::home_dir().as_deref())
165	}
166	
167	/// Expand an `[install] dir` value: `~` against `home`, else against
168	/// `cfg_dir` when relative.
169	fn expand_dir(cfg_dir: &Path, value: &str, home: Option<&Path>) -> Result<PathBuf, String> {
170	    let rest = if value == "~" {
171	        Some("")
172	    } else {
173	        value.strip_prefix("~/")
174	    };
175	    match rest {
176	        Some(rest) => home
177	            .map(|h| h.join(rest))
178	            .ok_or_else(|| format!("install: `install.dir` is '{value}' and HOME is not set")),
179	        None => Ok(crate::common::resolve_repo_path(cfg_dir, value)),
180	    }
181	}
182	
183	/// The manifest's version, `[package] version` in the `Cargo.toml` at
184	/// `root`.
185	pub fn manifest_version(root: &Path) -> Result<String, String> {
186	    let path = root.join("Cargo.toml");
187	    let map = crate::toml_simple::toml_load(&path)
188	        .map_err(|e| format!("install: cannot read '{}': {e}", path.display()))?;
189	    crate::toml_simple::toml_get(&map, "package.version")
190	        .cloned()
191	        .ok_or_else(|| format!("install: '{}' has no `[package] version`", path.display()))
192	}
193	
194	/// Run `bin -V` and return what it prints, `None` when it cannot be
195	/// run or fails.
196	fn run_version(bin: &Path) -> Option<String> {
197	    // Register entry 7 (clippy.toml): install runs the release binary
198	    // itself, `-V` alone, to report the binary it is about to copy.
199	    #[allow(clippy::disallowed_methods)]
200	    let out = std::process::Command::new(bin).arg("-V").output().ok()?;
201	    if !out.status.success() {
202	        return None;
203	    }
204	    String::from_utf8(out.stdout).ok()
205	}
206	
207	/// Parse `-V`'s output: the first line `<name> <version>[+<commit>[.<state>]] ...`
208	/// whose second word starts with a digit, so a line printed before the
209	/// version is passed over. `None` when no line has a version, which
210	/// install refuses as unreadable.
211	pub fn parse_reported(output: &str) -> Option<Reported> {
212	    let word = output.lines().find_map(|line| {
213	        line.split_whitespace()
214	            .nth(1)
215	            .filter(|w| w.starts_with(|c: char| c.is_ascii_digit()))
216	    })?;
217	    let (version, meta) = match word.split_once('+') {
218	        Some((v, m)) => (v, Some(m)),
219	        None => (word, None),
220	    };
221	    let (commit, state) = match meta {
222	        None => (None, None),
223	        Some(m) => match m.split_once('.') {
224	            Some((c, s)) => (Some(c.to_string()), Some(s.to_string())),
225	            None => (Some(m.to_string()), None),
226	        },
227	    };
228	    Some(Reported {
229	        version: version.to_string(),
230	        commit,
231	        state,
232	    })
233	}
234	
235	/// True when the commit prefix `c` names the commit id `id`.
236	fn names(c: &str, id: Option<&String>) -> bool {
237	    id.is_some_and(|id| id.starts_with(c))
238	}
239	
240	/// The report: what is being copied, one fact per line, for the user
241	/// to judge. Nothing in it refuses.
242	pub fn report(f: &Facts) -> Vec<String> {
243	    let mut out = Vec::new();
244	    let Some(r) = &f.reported else {
245	        return out;
246	    };
247	    let mut version = format!("version {}", r.version);
248	    if r.version.contains('-') {
249	        version.push_str(", a suffixed (pre-release) version");
250	    }
251	    if r.version != f.version {
252	        version.push_str(&format!(", the manifest's is {}", f.version));
253	    }
254	    out.push(version);
255	    match &r.commit {
256	        None => {
257	            out.push("commit unknown: the binary reports none".to_string());
258	            out.push("state unknown".to_string());
259	        }
260	        Some(c) => {
261	            let on_trunk = names(c, f.trunk.as_ref());
262	            let on_origin = names(c, f.trunk_origin.as_ref());
263	            let where_ = match (on_trunk, on_origin) {
264	                (true, true) => format!("`{TRUNK}` and `{TRUNK}@origin`"),
265	                (true, false) => format!("`{TRUNK}`, not yet `{TRUNK}@origin`"),
266	                (false, true) => format!("`{TRUNK}@origin`, not the local `{TRUNK}`"),
267	                (false, false) => format!("not `{TRUNK}`"),
268	            };
269	            out.push(format!("commit {c}, {where_}"));
270	            // A commit with no state after it is a clean build.
271	            let state = match &r.state {
272	                Some(s) => s.as_str(),
273	                None => "clean",
274	            };
275	            out.push(format!("state {state}"));
276	        }
277	    }
278	    out
279	}
280	
281	/// Every reason the copy itself would be wrong, empty when it may go.
282	pub fn refusals(f: &Facts, bin: &Path, dest: &Path) -> Vec<String> {
283	    let mut out = Vec::new();
284	    if !f.bin_exists {
285	        out.push(format!(
286	            "no binary at '{}': build it with `vc-x1 build`",
287	            bin.display()
288	        ));
289	    } else if f.reported.is_none() {
290	        out.push(format!("'{}' -V could not be run or read", bin.display()));
291	    }
292	    if !f.dest_dir_exists {
293	        // OK: dest is a directory joined with a file name, so it has a parent
294	        let dir = dest.parent().unwrap_or(dest);
295	        out.push(format!(
296	            "the `install.dir` directory '{}' does not exist",
297	            dir.display()
298	        ));
299	    }
300	    out
301	}
