303	/// Copy `bin` to `dest` as a temporary file beside it renamed into
304	/// place, so `dest` is never half written and a running copy of the
305	/// old binary is undisturbed. The temporary file is removed on failure.
306	pub fn deploy(bin: &Path, dest: &Path) -> Result<(), String> {
307	    // OK: dest is a directory joined with a file name, so both exist
308	    let dir = dest.parent().unwrap_or(Path::new("."));
309	    // OK: dest is joined with the release binary's file name, so it has one
310	    let name = dest
311	        .file_name()
312	        .map(|n| n.to_string_lossy().into_owned())
313	        .unwrap_or_default();
314	    let tmp = dir.join(format!(".{name}.vc-x1-install"));
315	    let result = std::fs::copy(bin, &tmp)
316	        .map_err(|e| format!("install: cannot copy to '{}': {e}", tmp.display()))
317	        .and_then(|_| {
318	            std::fs::rename(&tmp, dest).map_err(|e| {
319	                format!(
320	                    "install: cannot move '{}' into '{}': {e}",
321	                    tmp.display(),
322	                    dest.display()
323	                )
324	            })
325	        });
326	    if result.is_err() {
327	        std::fs::remove_file(&tmp).ok();
328	    }
329	    result
330	}
