content.content:
1	//! The `build` and `build-dev` subcommands: build the workspace's
2	//! release or its dev build, each by its configured command list. A
3	//! command per build, named with the `-dev` suffix as `run` and
4	//! `run-dev` are, so each names the build it makes and no dropped flag
5	//! makes the other. Neither touches the PATH: that is
6	//! `vc-x1 install`'s, which copies the release build there.
7	//!
8	//! - `vc-x1 build` runs `[build] release`, here
9	//!   `cargo build --release --locked`, and checks it left its binary
10	//!   at `[build] release-bin`. The lists leave the binaries in
11	//!   `target/`, off the PATH, so nothing there is replaced: the
12	//!   release build is run by `vc-x1 run` and copied by
13	//!   `vc-x1 install`, which runs this same build first, through
14	//!   [`build_params`] and [`build`].
15	//! - `vc-x1 build-dev` runs `[build] dev`, the dev build.
16	//! - Where a build leaves its binary is the config's to say,
17	//!   `release-bin` and `dev-bin`: vc-x1 never works it out from cargo
18	//!   or the package's name.
19	//! - Both run their commands with the build's [`Provenance`] in the
20	//!   environment, `VC_X1_BUILD_COMMIT` and `VC_X1_BUILD_STATE`, as
21	//!   `validate` does, so every build of a run sees the same values
22	//!   and none recompiles for another. An artifact that compiles them
23	//!   in can say what it was built from wherever it is copied. vc-x1
24	//!   does, as semver build metadata in its banner,
25	//!   `0.85.7+d70cf9ecdfd9`, `.dirty` for a build with edits.
26	//! - Neither checks the repo's state: a release may be built from a
27	//!   cycle's bookmark, to try the release profile mid-cycle.
28	//! - Neither tracks whether its binary is out of date: cargo does,
29	//!   rebuilding only what changed, so vc-x1 runs the list every time.
30	//! - The lists are run by [`crate::command_list`], as `validate`'s
31	//!   are.
32	
33	use std::path::{Path, PathBuf};
34	
35	use clap::Args;
36	use log::{debug, info, warn};
37	
38	use crate::context::Context;
39	use crate::subcommand::SubcommandRunner;
40	use crate::version::SourceState;
41	
42	/// The variable carrying the build's commit to its commands.
43	pub const BUILD_COMMIT_VAR: &str = "VC_X1_BUILD_COMMIT";
44	
45	/// The variable carrying `state`, the state of the source code being
46	/// compiled, `clean` or `dirty`.
47	pub const BUILD_STATE_VAR: &str = "VC_X1_BUILD_STATE";
48	
49	/// Build the release.
50	#[derive(Args, Debug)]
51	pub struct BuildArgs {
52	    /// Workspace to build from [default: the workspace containing
53	    /// the current directory]
54	    #[arg(short = 'R', long, value_name = "DIR")]
55	    pub repo: Option<PathBuf>,
56	}
57	
58	/// Build the dev build.
59	#[derive(Args, Debug)]
60	pub struct BuildDevArgs {
61	    /// Workspace to build from [default: the workspace containing
62	    /// the current directory]
63	    #[arg(short = 'R', long, value_name = "DIR")]
64	    pub repo: Option<PathBuf>,
65	}
66	
67	/// What a build is made from: the work repo's `@-` and the state of
68	/// its source, read before the build runs.
69	#[derive(Debug, Clone, PartialEq, Eq)]
70	pub struct Provenance {
71	    /// The full commit id of the work repo's `@-`.
72	    pub commit: String,
73	    /// The state of the source code being compiled: clean when the
74	    /// work repo's `@` was empty, so the compiled code is exactly
75	    /// `commit`'s tree, else dirty. Never unknown, since it is read
76	    /// through jj.
77	    pub state: SourceState,
78	}
79	
80	impl Provenance {
81	    /// Read the provenance of the work repo at `root`, `label`
82	    /// prefixing an error.
83	    pub fn read(root: &Path, label: &str) -> Result<Self, String> {
84	        let commit = crate::jj::cid_of(root, "@-")
85	            .map_err(|e| format!("{label}: the commit `@-` in '{}': {e}", root.display()))?;
86	        let empty = crate::jj::is_empty(root, "@")
87	            .map_err(|e| format!("{label}: whether `@` is empty in '{}': {e}", root.display()))?;
88	        let state = if empty {
89	            SourceState::Clean
90	        } else {
91	            SourceState::Dirty
92	        };
93	        Ok(Provenance { commit, state })
94	    }
95	
96	    /// Read it, or warn and carry none, for a build that runs
97	    /// without it: the dev build and `validate`'s.
98	    pub fn read_or_warn(root: &Path, label: &str) -> Option<Self> {
99	        match Self::read(root, label) {
100	            Ok(p) => Some(p),
101	            Err(e) => {
102	                warn!("{e}, so the build carries no commit");
103	                None
104	            }
105	        }
106	    }
107	
108	    /// The two variables the build's commands get.
109	    pub fn env(&self) -> [(&'static str, &str); 2] {
110	        [
111	            (BUILD_COMMIT_VAR, self.commit.as_str()),
112	            (BUILD_STATE_VAR, self.state.as_str()),
113	        ]
114	    }
115	}
116	
117	/// The variables for `provenance`, none when it is absent.
118	pub fn build_env(provenance: Option<&Provenance>) -> Vec<(&'static str, &str)> {
119	    // OK: no provenance is no variables, the build carrying no commit
120	    provenance.map(|p| p.env().to_vec()).unwrap_or_default()
121	}
