243	/// Run the list from the root with the provenance in its
244	/// environment, and for a release check it left its binary.
245	pub fn build(params: &BuildParams) -> Result<(), Box<dyn std::error::Error>> {
246	    debug!("{}: entry params={params:?}", params.label);
247	    let env = build_env(params.provenance.as_ref());
248	    crate::command_list::run(
249	        &params.root,
250	        params.key,
251	        &params.commands,
252	        &env,
253	        params.label,
254	    )?;
255	    let (Some(bin), Some(provenance)) = (&params.bin, &params.provenance) else {
256	        return Ok(());
257	    };
258	    if !bin.is_file() {
259	        return Err(format!(
260	            "build: `{}` passed but left no binary at '{}': check `build.release-bin`",
261	            params.key,
262	            bin.display()
263	        )
264	        .into());
265	    }
266	    let short = &provenance.commit[..provenance.commit.len().min(12)];
267	    let state = match provenance.state {
268	        SourceState::Clean => "state clean, `@` empty",
269	        _ => "state dirty, `@` held edits, so the build is not exactly that commit",
270	    };
271	    info!("build: {}, from {short}, {state}", bin.display());
272	    Ok(())
273	}
