123	/// Per-invocation build inputs: the command's label, the list's key,
124	/// its commands, the directory to run them from, the build's
125	/// provenance, and the binary a release leaves.
126	#[derive(Debug)]
127	pub struct BuildParams {
128	    /// `build` or `build-dev`, prefixing the run's messages.
129	    pub label: &'static str,
130	    /// `build.release` or `build.dev`.
131	    pub key: &'static str,
132	    /// The commands, one element per invocation.
133	    pub commands: Vec<String>,
134	    /// The work repo root the commands run from.
135	    pub root: PathBuf,
136	    /// The build's provenance, required for a release, best effort
137	    /// for the dev build.
138	    pub provenance: Option<Provenance>,
139	    /// The binary a release leaves, `[build] release-bin`, `None` for
140	    /// the dev build.
141	    pub bin: Option<PathBuf>,
142	}
143	
144	impl TryFrom<&BuildArgs> for BuildParams {
145	    type Error = String;
146	
147	    /// The release: see [`build_params`].
148	    fn try_from(a: &BuildArgs) -> Result<Self, String> {
149	        build_params(false, a.repo.as_deref())
150	    }
151	}
152	
153	impl TryFrom<&BuildDevArgs> for BuildParams {
154	    type Error = String;
155	
156	    /// The dev build: see [`build_params`].
157	    fn try_from(a: &BuildDevArgs) -> Result<Self, String> {
158	        build_params(true, a.repo.as_deref())
159	    }
160	}
161	
162	/// Resolve the workspace root (from `-R` or the cwd), take the chosen
163	/// list, read the provenance, and for a release resolve `release-bin`.
164	/// A release's every miss is an error here, before anything runs, and
165	/// the dev build's provenance is best effort.
166	pub fn build_params(dev: bool, repo: Option<&Path>) -> Result<BuildParams, String> {
167	    let (label, key) = if dev {
168	        ("build-dev", "build.dev")
169	    } else {
170	        ("build", "build.release")
171	    };
172	    let root = match repo {
173	        Some(p) => crate::common::find_workspace_root_from(p)
174	            .ok_or_else(|| format!("{label}: '{}' is not in a vc-x1 workspace", p.display()))?,
175	        None => crate::common::find_workspace_root()
176	            .ok_or_else(|| format!("{label}: not in a vc-x1 workspace (no config found)"))?,
177	    };
178	    let commands = crate::command_list::load(&root, key, label)?;
179	    let (provenance, bin) = if dev {
180	        (Provenance::read_or_warn(&root, label), None)
181	    } else {
182	        let bin = release_bin(&root)?;
183	        (Some(Provenance::read(&root, label)?), Some(bin))
184	    };
185	    Ok(BuildParams {
186	        label,
187	        key,
188	        commands,
189	        root,
190	        provenance,
191	        bin,
192	    })
193	}
194	
195	/// `[build] release-bin` at `root`, resolved against the config
196	/// file's directory, or as is when absolute. Required for a release,
197	/// whose build is checked for it and which `install` copies.
198	pub fn release_bin(root: &Path) -> Result<PathBuf, String> {
199	    let cfg = crate::config_md::load(root)
200	        .map_err(|e| format!("build: {e}"))?
201	        .ok_or_else(|| format!("build: no config in '{}'", root.display()))?;
202	    let value = crate::toml_simple::toml_get(&cfg.map, "build.release-bin").ok_or_else(|| {
203	        format!(
204	            "build: {}: no `build.release-bin`, the binary `build.release` leaves, \
205	             which `install` copies (see `vc-x1 config work`)",
206	            cfg.path.display()
207	        )
208	    })?;
209	    // OK: a loaded config's path is a file, so it has a parent
210	    let cfg_dir = cfg.path.parent().unwrap_or(root);
211	    Ok(crate::common::resolve_repo_path(cfg_dir, value))
212	}
