215	    type Params = BuildParams;
216	
217	    /// Delegate to the `TryFrom<&BuildArgs>` impl above.
218	    fn to_params(&self) -> Result<Self::Params, String> {
219	        BuildParams::try_from(self)
220	    }
221	
222	    /// Run the `build` op (`ctx` unused: the op is fully
223	    /// parameterized by `Params`).
224	    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
225	        build(params)
226	    }
227	}
