fn run_list(params: &InstallParams, list: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let bin = params.bin.to_string_lossy();
    // OK: dest is a directory joined with a file name, so it has a parent
    let dir = params
        .dest
        .parent()
        .unwrap_or(&params.dest)
        .to_string_lossy();
    let dest = params.dest.to_string_lossy();
    let env = [
        (INSTALL_BIN_VAR, bin.as_ref()),
        (INSTALL_DIR_VAR, dir.as_ref()),
        (INSTALL_DEST_VAR, dest.as_ref()),
    ];
    crate::command_list::run(&params.root, params.list_key, list, &env, params.label)
}

