/// real problem (both carriers present, unreadable file, a bad
/// fence), never a plain miss.
pub fn load(dir: &Path) -> Result<Option<VcConfig>, Box<dyn std::error::Error>> {
    let Some(path) = vc_config_path(dir)? else {
